mean_nonconsistent = np.mean(first2)

std_CONSISTENT = np.std(first1)
std_NONCONSISTENT = np.std(first2)

# 2. 计算偏移值
offset = mean_consistent - mean_nonconsistent

# 3. 进行 t 检验
t_statistic, p_value_t = ttest_ind(first1, first2)

# 输出结果
